    }
}

package com.example.starter.costmap.domain;

import java.util.Comparator;

/**
 * 多来源同格主张的确定性合并规则（公开决胜顺序）：
 * <ol>
 *   <li>priority 数值大者胜；</li>
 *   <li>priority 相同，观测时间戳 eventTime 晚者胜（更新的观测胜）；</li>
 *   <li>仍相同，sourceId 字典序小者胜；</li>
 *   <li>仍相同，obstacleId 字典序小者胜；</li>
 *   <li>仍相同，应用序号 seq 大者胜（同来源同障碍的新版本胜）。</li>
 * </ol>
 */
public final class MergePolicy {

    /** 获胜声明比较器：排在前面（更大）的声明获胜。 */
    public static final Comparator<ObstacleStatement> WINNER = null;

    private MergePolicy() {
    }
}

package com.example.starter.costmap.domain;

/**
 * Nav2 inflation layer 风格的膨胀代价计算。
 *
 * <p>代价取值 0..254：254 致命障碍、253 内切障碍、1..252 按指数衰减、0 无影响。</p>
 */
public final class Inflation {

    private Inflation() {
    }

    /**
     * 按 Nav2 公式计算距最近致命障碍 {@code distance} 个单元格处的膨胀代价。
     *
     * <p>{@code distance == 0} 返回 254；{@code 0 < distance <= inscribedRadius}
     * 返回 253；内切半径之外、膨胀半径之内按
     * {@code 251 * exp(-costScalingFactor * (distance - inscribedRadius))} 衰减并截断到
     * [1,252]；膨胀半径之外返回 0。</p>
     */
    public static int inflateCost(double distance,
                                  double inscribedRadius,
                                  double inflationRadius,
                                  double costScalingFactor) {
        throw new UnsupportedOperationException("skeleton");
    }
}

package com.example.starter.costmap.domain;

/**
 * 行优先 {@code int[width * height]} 栅格与 BLOB 之间的编解码。
 */
public final class GridCodec {

    private GridCodec() {
    }

    /** 栅格编码为 4 字节大端 int 数组。 */
    public static byte[] encode(int[] cells) {
        throw new UnsupportedOperationException("skeleton");
    }

    /** BLOB 解码为栅格，并校验长度。 */
    public static int[] decode(byte[] data, int expectedLength) {
        throw new UnsupportedOperationException("skeleton");
    }
}

