package com.example.starter.costmap.web;

import org.springframework.http.HttpStatus;

/**
 * 业务错误码与稳定错误语义。错误响应统一为
 * {@code {"error": code, "message": ..., "requestId": ...}}，code 对客户端稳定。
 */
public enum ErrorCode {

    /** 请求体或参数非法（400）。 */
    BAD_REQUEST(HttpStatus.BAD_REQUEST, "BAD_REQUEST"),

    /** 区域为空、反转或越出地图边界（400）。 */
    INVALID_REGION(HttpStatus.BAD_REQUEST, "INVALID_REGION"),

    /** 指定的地图版本/快照不存在（404）。 */
    MAP_NOT_FOUND(HttpStatus.NOT_FOUND, "MAP_NOT_FOUND"),

    /** 快照不存在（404）。 */
    SNAPSHOT_NOT_FOUND(HttpStatus.NOT_FOUND, "SNAPSHOT_NOT_FOUND"),

    /** 同一 requestId 已应用且参数不同（409）。 */
    IDEMPOTENCY_CONFLICT(HttpStatus.CONFLICT, "IDEMPOTENCY_CONFLICT"),

    /** 地图/快照 ID 冲突，已存在（409）。 */
    VERSION_CONFLICT(HttpStatus.CONFLICT, "VERSION_CONFLICT"),

    /** 并发更新乐观锁冲突（409）。 */
    CONCURRENT_UPDATE(HttpStatus.CONFLICT, "CONCURRENT_UPDATE"),

    /** 服务端内部错误（500）。 */
    INTERNAL_ERROR(HttpStatus.INTERNAL_SERVER_ERROR, "INTERNAL_ERROR");

    private final HttpStatus httpStatus;
    private final String code;

    ErrorCode(HttpStatus httpStatus, String code) {
        this.httpStatus = httpStatus;
        this.code = code;
    }

    public HttpStatus httpStatus() {
        return httpStatus;
    }

    public String code() {
        return code;
    }
}

package com.example.starter.costmap.web;

/**
 * 业务异常，携带稳定 {@link ErrorCode}。
 */
public class ApiException extends RuntimeException {

    private final ErrorCode errorCode;

    public ApiException(ErrorCode errorCode, String message) {
        super(message);
        this.errorCode = errorCode;
    }

    public ErrorCode errorCode() {
        return errorCode;
    }
}

package com.example.starter.costmap.web;

import java.time.Instant;

/**
 * 稳定错误响应体。
 *
 * @param error     稳定错误码
 * @param message   人类可读信息（不含堆栈）
 * @param requestId 触发错误的幂等请求 ID（无则为 null）
 * @param timestamp 错误发生时刻（epoch 毫秒）
 */
public record ErrorResponse(String error, String message, String requestId, long timestamp) {

    public static ErrorResponse of(ErrorCode code, String message, String requestId) {
        return new ErrorResponse(code.code(), message, requestId, Instant.now().toEpochMilli());
    }
}

package com.example.starter.costmap.web;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.ResponseEntity;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

/**
 * 统一异常处理：业务异常映射为稳定错误码，参数校验异常映射为 400。
 */
@RestControllerAdvice
public class GlobalExceptionHandler {

    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    @ExceptionHandler(ApiException.class)
    public ResponseEntity<ErrorResponse> handleApi(ApiException ex) {
        return ResponseEntity.status(ex.errorCode().httpStatus())
                .body(ErrorResponse.of(ex.errorCode(), ex.getMessage(), null));
    }

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<ErrorResponse> handleValidation(MethodArgumentNotValidException ex) {
        throw new UnsupportedOperationException("skeleton");
    }

    @ExceptionHandler(HttpMessageNotReadableException.class)
    public ResponseEntity<ErrorResponse> handleUnreadable(HttpMessageNotReadableException ex) {
        throw new UnsupportedOperationException("skeleton");
    }

    @ExceptionHandler(Exception.class)
    public ResponseEntity<ErrorResponse> handleOther(Exception ex) {
        throw new UnsupportedOperationException("skeleton");
    }
}

