    public RegionDiffResponse diffRegion(@PathVariable String mapId,
                                         @PathVariable String snapshotId,
                                         @RequestParam int x0,
                                         @RequestParam int y0,
                                         @RequestParam int x1,
                                         @RequestParam int y1) {
