package com.example.starter.costmap.domain;

import org.junit.jupiter.api.Test;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * 膨胀代价公式测试：致命/内切/指数衰减/越界四段语义。
 */
class InflationTest {

    @Test
    void lethalAtZeroDistance() {
        assertThat(Inflation.inflateCost(0.0, 1.0, 3.0, 2.0)).isEqualTo(254);
    }

    @Test
    void inscribedWithinInscribedRadius() {
        assertThat(Inflation.inflateCost(0.5, 1.0, 3.0, 2.0)).isEqualTo(253);
        assertThat(Inflation.inflateCost(1.0, 1.0, 3.0, 2.0)).isEqualTo(253);
    }

    @Test
    void decayMonotonicallyBetweenRadii() {
        int prev = Integer.MAX_VALUE;
        for (int d = 2; d <= 6; d++) {
            int cost = Inflation.inflateCost(d, 1.0, 6.0, 1.0);
            assertThat(cost).isBetween(1, 252);
            assertThat(cost).isLessThan(prev);
            prev = cost;
        }
    }

    @Test
    void zeroOutsideInflationRadius() {
        assertThat(Inflation.inflateCost(3.01, 1.0, 3.0, 2.0)).isZero();
        assertThat(Inflation.inflateCost(10.0, 1.0, 3.0, 2.0)).isZero();
    }

    @Test
    void higherScalingFactorDecaysFaster() {
        int slow = Inflation.inflateCost(2.0, 1.0, 5.0, 0.5);
        int fast = Inflation.inflateCost(2.0, 1.0, 5.0, 3.0);
        assertThat(fast).isLessThan(slow);
    }
}

package com.example.starter.costmap.domain;

import org.junit.jupiter.api.Test;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * 确定性合并决胜顺序测试：优先级 &gt; 时间戳 &gt; 来源 ID &gt; 障碍 ID &gt; 序号。
 */
class MergePolicyTest {

    private final CellRegion region = new CellRegion(0, 0, 1, 1);

    private ObstacleStatement stmt(long seq, String source, String obstacle,
                                   int priority, long eventTime) {
        return new ObstacleStatement(seq, "req-" + seq, source, obstacle, priority,
                StatementKind.OCCUPY, region, eventTime, 10_000L,
                eventTime + 10_000L, eventTime);
    }

    @Test
    void higherPriorityWins() {
        ObstacleStatement low = stmt(1, "sensor-a", "o", 1, 100L);
        ObstacleStatement high = stmt(2, "sensor-b", "o", 5, 50L);
        assertThat(MergePolicy.winner(low, high)).isEqualTo(high);
        // 与物理顺序无关
        assertThat(MergePolicy.winner(high, low)).isEqualTo(high);
    }

    @Test
    void laterEventTimeWinsOnTiedPriority() {
        ObstacleStatement older = stmt(1, "sensor-a", "o", 3, 100L);
        ObstacleStatement newer = stmt(2, "sensor-z", "o", 3, 200L);
        assertThat(MergePolicy.winner(older, newer)).isEqualTo(newer);
    }

    @Test
    void sourceIdLexicographicBreaksTie() {
        ObstacleStatement a = stmt(1, "sensor-a", "o", 3, 100L);
        ObstacleStatement b = stmt(2, "sensor-b", "o", 3, 100L);
        assertThat(MergePolicy.winner(a, b)).isEqualTo(a);
    }

    @Test
    void obstacleIdThenSeqBreakRemainingTies() {
        ObstacleStatement o1 = stmt(1, "sensor-a", "aaa", 3, 100L);
        ObstacleStatement o2 = stmt(2, "sensor-a", "bbb", 3, 100L);
        assertThat(MergePolicy.winner(o1, o2)).isEqualTo(o1);

        ObstacleStatement v1 = stmt(1, "sensor-a", "same", 3, 100L);
        ObstacleStatement v2 = stmt(7, "sensor-a", "same", 3, 100L);
        assertThat(MergePolicy.winner(v1, v2)).isEqualTo(v2);
    }

    @Test
    void nullSafety() {
        ObstacleStatement s = stmt(1, "a", "o", 1, 100L);
        assertThat(MergePolicy.winner(null, s)).isSameAs(s);
        assertThat(MergePolicy.winner(s, null)).isSameAs(s);
    }
}

package com.example.starter.costmap.domain;

import com.example.starter.costmap.web.ApiException;
import org.junit.jupiter.api.Test;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/**
 * 区域几何与校验测试。
 */
class CellRegionTest {

    @Test
    void areaContainsIntersects() {
        CellRegion r = new CellRegion(1, 2, 3, 4);
        assertThat(r.area()).isEqualTo(9);
        assertThat(r.contains(1, 2)).isTrue();
        assertThat(r.contains(3, 4)).isTrue();
        assertThat(r.contains(0, 2)).isFalse();
        assertThat(r.intersects(new CellRegion(3, 4, 5, 5))).isTrue();
        assertThat(r.intersects(new CellRegion(4, 2, 5, 4))).isFalse();
    }

    @Test
    void validateRejectsReversedAndOutOfBounds() {
        assertThatThrownBy(() -> new CellRegion(2, 0, 1, 1).validateWithin(5, 5))
                .isInstanceOf(ApiException.class);
        assertThatThrownBy(() -> new CellRegion(-1, 0, 1, 1).validateWithin(5, 5))
                .isInstanceOf(ApiException.class);
        assertThatThrownBy(() -> new CellRegion(0, 0, 5, 1).validateWithin(5, 5))
                .isInstanceOf(ApiException.class);
        assertThat(new CellRegion(0, 0, 4, 4).validateWithin(5, 5).area()).isEqualTo(25);
    }

    @Test
    void expandClipsToMap() {
        CellRegion r = new CellRegion(0, 0, 1, 1).expandAndClip(3, 6, 6);
        assertThat(r).isEqualTo(new CellRegion(0, 0, 4, 4));
        CellRegion corner = new CellRegion(4, 4, 5, 5).expandAndClip(3, 6, 6);
        assertThat(corner).isEqualTo(new CellRegion(1, 1, 5, 5));
    }

    @Test
    void unionBoundingBox() {
        assertThat(new CellRegion(0, 0, 1, 1).union(new CellRegion(4, 3, 5, 5)))
                .isEqualTo(new CellRegion(0, 0, 5, 5));
    }
}

